<template>
  <div class="storyboard-overlay" @click.self="close">
    <section ref="dialog" class="storyboard-dialog" tabindex="-1" role="dialog" aria-modal="true" :aria-label="t('Storyboard editor', 'Bảng phân cảnh')">
      <header class="storyboard-header"><div><h2>▦ {{ t('STORYBOARD', 'BẢNG PHÂN CẢNH') }}</h2><p>{{ projectTitle }} · {{ shots.length }} {{ t('scenes', 'cảnh') }} · {{ totalDuration }}s</p></div><button type="button" :disabled="saving || importBusy" :aria-label="t('Close storyboard', 'Đóng bảng phân cảnh')" @click="close">×</button></header>
      <nav class="storyboard-tabs" :aria-label="t('Storyboard tools', 'Công cụ phân cảnh')"><button type="button" :disabled="importBusy" :aria-pressed="tab === 'current'" @click="tab='current'">{{ t('Current storyboard', 'Bảng phân cảnh hiện tại') }}</button><button type="button" :disabled="!canEdit || busy || saving" :aria-pressed="tab === 'import'" @click="tab='import'">{{ t('Import grid image', 'Nhập ảnh dạng lưới') }}</button></nav>
      <template v-if="tab === 'current'">
        <div class="storyboard-toolbar"><span>{{ t('Descriptions stay as drafts until Save. Adding, moving and removing scenes apply immediately.', 'Mô tả là bản nháp đến khi bấm Lưu. Thêm, đổi thứ tự và gỡ cảnh được áp dụng ngay.') }}</span><button type="button" :disabled="blocked" @click="addScene">＋ {{ t('Add scene', 'Thêm cảnh') }}</button></div>
        <p v-if="error" class="storyboard-error" role="alert">{{ error }} <button type="button" :disabled="saving" @click="reloadSaved">{{ t('Reload saved data', 'Tải lại dữ liệu đã lưu') }}</button></p><p v-if="message" class="storyboard-message" role="status">{{ message }}</p>
        <div v-if="shots.length" class="storyboard-content">
          <ol class="storyboard-scenes" :aria-label="t('Current scenes', 'Các cảnh hiện tại')">
            <li v-for="(shot,index) in shots" :key="shot.name"><button type="button" class="storyboard-card" :class="{selected:activeShot?.name === shot.name}" :aria-pressed="activeShot?.name === shot.name" :data-storyboard-scene="shot.name" @click="selectedName=shot.name; emit('select-shot',shot,index)">
              <div class="storyboard-thumb"><img v-if="frameFor(shot)" :src="frameFor(shot)" :alt="shot.shot_name" /><video v-else-if="shot.output_video || shot.selected_output_file" :src="shot.output_video || shot.selected_output_file" muted playsinline preload="metadata" /><span v-else>▧<small>{{ t('No image yet', 'Chưa có ảnh') }}</small></span><b>{{ index+1 }}</b></div>
              <div class="storyboard-card-copy"><strong>{{ drafts[shot.name]?.title || shot.shot_name || `${t('Scene','Cảnh')} ${index+1}` }}</strong><p>{{ drafts[shot.name]?.description || descriptionFor(shot) }}</p><small>{{ secondsLabel(drafts[shot.name]?.duration ?? shot.duration_seconds) }}s <em v-if="dirty(shot.name)">· {{ t('Unsaved', 'Chưa lưu') }}</em><em v-else-if="stale(shot)">· {{ t('Image needs updating', 'Ảnh cần cập nhật') }}</em></small></div>
            </button></li>
          </ol>
          <aside v-if="activeShot && activeDraft" class="storyboard-inspector">
            <div class="storyboard-inspector-head"><strong>{{ t('Scene', 'Cảnh') }} {{ activeShot.shot_number }}</strong><div><button type="button" :disabled="blocked || activeIndex<=0" :aria-label="t('Move scene earlier','Đưa cảnh lên trước')" @click="move(-1)">↑</button><button type="button" :disabled="blocked || activeIndex>=shots.length-1" :aria-label="t('Move scene later','Đưa cảnh ra sau')" @click="move(1)">↓</button></div></div>
            <div class="storyboard-inspector-fields"><label>{{ t('Scene name','Tên cảnh') }}<input v-model="activeDraft.title" maxlength="140" :disabled="blocked" /></label>
            <label>{{ t('Scene description','Mô tả cảnh') }}<textarea v-model="activeDraft.description" rows="6" maxlength="8000" :disabled="blocked" /></label>
            <div class="storyboard-field-row"><label>{{ t('Duration (seconds)','Thời lượng (giây)') }}<input :value="secondsInput(activeDraft.duration)" @input="activeDraft.duration = Number($event.target.value)" type="number" min="1" max="60" step="0.1" :disabled="blocked" /></label><label>{{ t('Transition into scene','Cách bắt đầu cảnh') }}<select v-model="activeDraft.continuity" :disabled="blocked"><option value="New Scene">{{ t('New scene','Cảnh mới') }}</option><option value="Continue" :disabled="activeIndex===0">{{ t('Continue previous scene','Tiếp nối cảnh trước') }}</option></select></label></div>
            <label>{{ t('On-screen caption (optional)','Chữ trên video (không bắt buộc)') }}<input v-model="activeDraft.caption" maxlength="120" :disabled="blocked" /></label>
            <p class="storyboard-note">{{ t('Duration changes update the total video length; other scenes keep their timing. Saving does not regenerate images, clips or the timeline.', 'Đổi thời lượng sẽ đổi tổng độ dài video; thời lượng các cảnh khác được giữ nguyên. Lưu không tự tạo lại ảnh, video hoặc dòng thời gian.') }}</p>
            <div v-if="activeShot.references?.length" class="storyboard-references"><strong>{{ t('Scene references','Tư liệu của cảnh') }}</strong><span v-for="reference in activeShot.references" :key="reference.reference_key || reference.asset_version">{{ referenceLabel(reference, assets) }}</span></div>
            
            <div class="storyboard-actions"><button type="button" :disabled="saving" @click="openTools">{{ canEdit ? t('Image, references & scene tools','Ảnh, tư liệu & công cụ cảnh') : t('View scene on canvas','Xem cảnh trên canvas') }}</button><button type="button" class="storyboard-remove" :disabled="blocked" @click="remove">{{ t('Remove scene','Gỡ cảnh') }}</button></div></div>
            <div class="storyboard-actions"><button type="button" class="storyboard-primary" :disabled="blocked || !dirty(activeShot.name) || !validDraft" @click="save">{{ saving ? '…' : t('Save scene','Lưu cảnh') }}</button><button type="button" :disabled="saving || !dirty(activeShot.name)" @click="resetDraft(activeShot)">{{ t('Discard changes','Bỏ thay đổi') }}</button></div>
          </aside>
        </div>
        <div v-else class="storyboard-empty"><h3>{{ t('No scenes in this video yet','Video này chưa có cảnh') }}</h3><p>{{ t('Add a blank scene to write the storyboard, or import a grid image. No generation starts automatically.', 'Thêm cảnh trống để viết phân cảnh, hoặc nhập ảnh dạng lưới. Không tự bắt đầu tạo video.') }}</p><button type="button" :disabled="blocked" @click="addScene">＋ {{ t('Add first scene','Thêm cảnh đầu tiên') }}</button></div>
        <footer class="storyboard-footer"><span>{{ unsavedCount ? t(`${unsavedCount} scene(s) have unsaved changes`,`${unsavedCount} cảnh có thay đổi chưa lưu`) : t('Showing this video’s saved storyboard','Đang hiển thị phân cảnh đã lưu của video này') }}</span><button type="button" :disabled="saving" @click="close">{{ t('Done','Xong') }}</button></footer>
      </template>
      <StoryboardSlicer v-else embedded :project-name="projectName" :shots="shots" :current-lang="currentLang" @close="tab='current'" @busy-change="importBusy=$event" @done="imported" />
    </section>
  </div>
</template>

<script setup>
import { computed, reactive, ref, watch } from 'vue';
import { call } from 'frappe-ui';
import StoryboardSlicer from './StoryboardSlicer.vue';
import { referenceLabel } from '../../utils/rioPresentation.js';
import { errorMessage } from '../../utils/errors';
import { rioConfirm } from '../../utils/rioDialog';
import { useDialogFocus } from '../../composables/useDialogFocus';
const props = defineProps({ projectName:String, projectTitle:String, currentLang:{type:String,default:'vi'}, shots:{type:Array,default:()=>[]}, assets:{type:Array,default:()=>[]}, frames:{type:Array,default:()=>[]}, selectedShotIndex:{type:Number,default:0}, canEdit:Boolean, busy:Boolean });
const emit = defineEmits(['close','changed','select-shot','edit-shot']);
const t=(en,vi)=>props.currentLang==='vi'?vi:en;
const dialog=ref(null),tab=ref('current'),selectedName=ref(props.shots[props.selectedShotIndex]?.name || ''),saving=ref(false),error=ref(''),message=ref('');
const importBusy=ref(false);
const drafts=reactive({}),baselines=reactive({});
const activeShot=computed(()=>props.shots.find(shot=>shot.name===selectedName.value) || props.shots[0]);
const activeIndex=computed(()=>props.shots.findIndex(shot=>shot.name===activeShot.value?.name));
const activeDraft=computed(()=>drafts[activeShot.value?.name]);
const blocked=computed(()=>!props.canEdit || props.busy || saving.value);
const totalDuration=computed(()=>Number(props.shots.reduce((sum,shot)=>sum+Number(shot.duration_seconds||0),0).toFixed(2)));
const secondsLabel=value=>Number(Number(value||0).toFixed(2));
const secondsInput=value=>Number(Number(value||0).toFixed(3));
const signature=draft=>JSON.stringify(draft && [draft.title,draft.description,draft.duration,draft.continuity,draft.caption]);
const dirty=name=>Boolean(drafts[name] && signature(drafts[name])!==baselines[name]);
const unsavedCount=computed(()=>props.shots.filter(shot=>dirty(shot.name)).length);
const validDraft=computed(()=>activeDraft.value?.title?.trim() && activeDraft.value?.description?.trim() && Number(activeDraft.value.duration)>=1 && Number(activeDraft.value.duration)<=60);
function descriptionFor(shot){return shot.storyboard_action || shot.generation_prompt || shot.authored_action || '';}
function resetDraft(shot){drafts[shot.name]={title:shot.shot_name || `${t('Scene','Cảnh')} ${shot.shot_number}`,description:descriptionFor(shot),duration:Number(shot.duration_seconds||5),continuity:shot.continuity_mode||'New Scene',caption:shot.caption||'',modified:shot.modified};baselines[shot.name]=signature(drafts[shot.name]);}
watch(()=>props.shots,shots=>{for(const shot of shots)if(!drafts[shot.name] || !dirty(shot.name))resetDraft(shot);},{immediate:true,deep:true});
function frameFor(shot){return props.frames.find(frame=>frame.shot===shot.name)?.url || shot.reference_image || shot.first_frame_image || shot.illustration || '';}
function stale(shot){return props.frames.find(frame=>frame.shot===shot.name)?.stale || shot.is_outdated;}
async function close(){if(saving.value || importBusy.value)return false;if(unsavedCount.value && !await rioConfirm(t('Discard unsaved storyboard changes?','Bỏ các thay đổi phân cảnh chưa lưu?'),{destructive:true}))return false;emit('close');return true;}
useDialogFocus(dialog,close);
async function reloadSaved(){if(unsavedCount.value && !await rioConfirm(t('Discard local drafts and reload saved scenes?','Bỏ bản nháp và tải lại các cảnh đã lưu?'),{destructive:true}))return;for(const key of Object.keys(drafts))delete drafts[key];for(const shot of props.shots)resetDraft(shot);error.value='';emit('changed');}
async function mutate(action){if(blocked.value)return; saving.value=true;error.value='';message.value='';try{await action();emit('changed');}catch(err){error.value=errorMessage(err,t('Could not update storyboard.','Không thể cập nhật phân cảnh.'));}finally{saving.value=false;}}
function save(){const shot=activeShot.value,draft={...activeDraft.value};return mutate(async()=>{const result=await call('joymedia.services.planning.storyboard_grid.update_scene',{project_name:props.projectName,shot_name:shot.name,title:draft.title,description:draft.description,duration_seconds:draft.duration,continuity:draft.continuity,caption:draft.caption,expected_modified:draft.modified,description_changed:draft.description!==descriptionFor(shot)});drafts[shot.name]={...draft,...result};baselines[shot.name]=signature(drafts[shot.name]);message.value=t('Scene saved. Review the updated storyboard before regenerating media.','Đã lưu cảnh. Duyệt phân cảnh mới trước khi tạo lại tư liệu.');});}
function addScene(){return mutate(async()=>{const result=await call('joymedia.services.planning.storyboard_grid.add_blank_scene',{project_name:props.projectName});selectedName.value=result.shot;});}
function move(delta){const shot=activeShot.value;return mutate(()=>call('joymedia.api.storyboard.reorder_project_shot',{project_name:props.projectName,shot_name:shot.name,target_shot_number:activeIndex.value+delta+1}));}
async function remove(){const shot=activeShot.value;if(!shot || blocked.value)return;if(!await rioConfirm(t('Remove this scene and its timeline clips? Original media files are kept.','Gỡ cảnh này và các đoạn tương ứng trên dòng thời gian? Tệp tư liệu gốc vẫn được giữ.'),{destructive:true}))return;await mutate(async()=>{let result=await call('joymedia.api.storyboard.remove_project_scene',{project_name:props.projectName,shot_name:shot.name});if(result.requires_confirmation){if(!await rioConfirm(result.message,{destructive:true}))return;result=await call('joymedia.api.storyboard.remove_project_scene',{project_name:props.projectName,shot_name:shot.name,confirm_continuation:true});}if(result.removed){delete drafts[shot.name];delete baselines[shot.name];selectedName.value=props.shots.find(item=>item.name!==shot.name)?.name || '';}});}
async function openTools(){const shot=activeShot.value,index=activeIndex.value;if(await close()){if(props.canEdit)emit('edit-shot',shot,index);else emit('select-shot',shot,index);}}
function imported(result){importBusy.value=false;tab.value='current';message.value=t(`${result.panels} scenes imported.`, `Đã nhập ${result.panels} cảnh.`);selectedName.value=result.shots?.[0] || selectedName.value;emit('changed');}
</script>

<style scoped>
.storyboard-overlay{position:fixed;inset:0;z-index:90;display:grid;place-items:center;padding:20px;background:#03060bc9;backdrop-filter:blur(5px)}.storyboard-dialog{display:flex;flex-direction:column;width:min(1280px,100%);height:min(840px,92vh);min-height:0;overflow:hidden;border:1px solid #295569;border-radius:14px;background:#0e151f;color:#e7f2f7;font:13px/1.5 Inter,system-ui,sans-serif;box-shadow:0 20px 60px #000b}.storyboard-header{display:flex;justify-content:space-between;align-items:center;padding:16px 20px;border-bottom:1px solid #243747}.storyboard-header h2{color:#44e0ee;font-size:16px;font-weight:800;letter-spacing:1px}.storyboard-header p{color:#91acbb;margin:4px 0 0}.storyboard-header>button{font-size:26px}.storyboard-tabs{display:flex;gap:8px;padding:12px 20px;border-bottom:1px solid #243747}.storyboard-dialog button{padding:6px 10px;border:1px solid #2a475b;border-radius:7px;color:#9ee8f0;background:#102431}.storyboard-dialog button:disabled{opacity:.4;cursor:not-allowed}.storyboard-tabs button[aria-pressed=true]{color:#55e5f0;border-color:#14a9bc;background:#0a3542}.storyboard-toolbar{display:flex;justify-content:space-between;align-items:center;gap:16px;padding:10px 20px;color:#93adbb;font-size:12px}.storyboard-content{display:flex;flex:1;min-height:0;border-top:1px solid #243747}.storyboard-scenes{display:grid;grid-template-columns:repeat(auto-fill,minmax(205px,1fr));align-content:start;gap:14px;flex:1;overflow:auto;padding:16px;margin:0;list-style:none}.storyboard-scenes li{min-width:0}.storyboard-scenes .storyboard-card{padding:0;width:100%;height:100%;overflow:hidden;text-align:left;border-color:#293d51;background:#121d29;color:#e6f2f6}.storyboard-card.selected{border-color:#20d5e7;box-shadow:0 0 0 1px #20d5e755}.storyboard-thumb{position:relative;aspect-ratio:16/9;display:grid;place-items:center;background:#070c13}.storyboard-thumb img,.storyboard-thumb video{width:100%;height:100%;object-fit:contain;position:absolute}.storyboard-thumb>span{display:flex;flex-direction:column;align-items:center;color:#6d8798;font-size:24px}.storyboard-thumb small{font-size:11px}.storyboard-thumb b{position:absolute;top:8px;left:8px;background:#06131bd9;color:#5ce9f3;border:1px solid #2b6173;border-radius:5px;padding:1px 7px}.storyboard-card-copy{padding:10px}.storyboard-card-copy strong{display:block;font-size:12px}.storyboard-card-copy p{display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden;margin:5px 0 8px;color:#adc0cc;font-size:12px}.storyboard-card-copy small{color:#86b4c4}.storyboard-card-copy em{color:#f5ca78;font-style:normal}.storyboard-inspector{width:350px;flex:none;padding:16px;overflow:hidden;display:flex;flex-direction:column;border-left:1px solid #243747;background:#101b27}.storyboard-inspector-fields{flex:1;min-height:0;overflow:auto;padding-right:3px}.storyboard-inspector>.storyboard-actions{flex:none;border-top:1px solid #243747;padding-top:12px}.storyboard-inspector-head{flex:none;display:flex;align-items:center;justify-content:space-between;color:#7cebf4;margin-bottom:12px}.storyboard-inspector-head button{margin-left:5px}.storyboard-inspector label{display:block;margin:10px 0;color:#a9c1cf;font-size:12px}.storyboard-inspector input,.storyboard-inspector textarea,.storyboard-inspector select{display:block;width:100%;margin-top:5px;border:1px solid #2c4559;border-radius:6px;padding:8px;background:#080f18;color:#eff8ff;font:inherit}.storyboard-inspector textarea{resize:vertical;min-height:120px}.storyboard-field-row{display:flex;gap:10px}.storyboard-field-row label{flex:1;min-width:0}.storyboard-note{color:#7897a9;font-size:11px;line-height:1.6}.storyboard-actions{display:flex;gap:8px;margin-top:12px;flex-wrap:wrap}.storyboard-actions .storyboard-primary{background:#087589;border-color:#0bb6ca;color:#f0fdff}.storyboard-actions .storyboard-remove{color:#fca5b1}.storyboard-references{display:flex;flex-wrap:wrap;gap:5px;margin:12px 0}.storyboard-references strong{width:100%;font-size:11px;color:#89b6c7}.storyboard-references span{padding:2px 6px;border:1px solid #27495d;border-radius:5px;color:#a5c3d3;font-size:10px}.storyboard-footer{display:flex;align-items:center;justify-content:space-between;padding:12px 20px;border-top:1px solid #243747;color:#8ba8b8;font-size:12px}.storyboard-empty{flex:1;display:flex;align-items:center;justify-content:center;flex-direction:column;padding:30px;text-align:center;color:#99b5c5}.storyboard-empty h3{font-size:19px;color:#e6f7fa}.storyboard-empty p{max-width:500px;margin:12px 0 20px}.storyboard-error,.storyboard-message{margin:0;padding:8px 20px;font-size:12px}.storyboard-error{color:#fda4af}.storyboard-message{color:#74dfbd}
@media(max-width:850px){.storyboard-content{flex-direction:column;overflow:auto}.storyboard-scenes{flex:none;overflow:visible}.storyboard-inspector{width:100%;border-left:0;border-top:1px solid #243747;overflow:visible}.storyboard-toolbar{align-items:start}.storyboard-overlay{padding:8px}.storyboard-dialog{height:95vh}.storyboard-header,.storyboard-tabs{padding:12px}}
</style>
